import React, { useState, useEffect } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import {
  Container,
  Grid,
  Paper,
  Typography,
  Button,
  Box,
  Rating,
  TextField,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
  Avatar,
  Divider,
  Tabs,
  Tab,
  Link,
  CircularProgress,
  Alert,
  ListItemIcon,
  Card,
  CardMedia,
  CardContent,
  Chip
} from '@mui/material';
import YouTube from 'react-youtube';
import axios from 'axios';
import { format } from 'date-fns';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import LinkIcon from '@mui/icons-material/Link';
import CommentIcon from '@mui/icons-material/Comment';
import StarIcon from '@mui/icons-material/Star';
import ContentCard from './ContentCard';

const MovieDetails = () => {
  const { id } = useParams();
  const [searchParams] = useSearchParams();
  const type = searchParams.get('type') || 'movie';
  const [content, setContent] = useState(null);
  const [error, setError] = useState('');
  const [comment, setComment] = useState('');
  const [userRating, setUserRating] = useState(0);
  const [activeTab, setActiveTab] = useState(0);
  const [providers, setProviders] = useState(null);
  const [similarContent, setSimilarContent] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchContentDetails = async () => {
      try {
        setLoading(true);
        const token = localStorage.getItem('token');
        const config = {
          headers: {
            'x-auth-token': token
          }
        };

        const [detailsRes, providersRes, similarRes] = await Promise.all([
          axios.get(`/api/movies/${id}?type=${type}`, config),
          axios.get(`/api/movies/${id}/providers?type=${type}`, config),
          axios.get(`/api/movies/${id}/similar?type=${type}`, config)
        ]);

        setContent(detailsRes.data);
        setProviders(providersRes.data);
        setSimilarContent(similarRes.data.results || []);
        setError(null);
      } catch (err) {
        console.error('Error fetching content details:', err);
        setError(err.response?.data?.msg || 'Error fetching content details');
      } finally {
        setLoading(false);
      }
    };

    fetchContentDetails();
  }, [id, type]);

  const handleAddToHistory = async () => {
    try {
      const token = localStorage.getItem('token');
      const config = {
        headers: {
          'x-auth-token': token,
        },
      };
      await axios.post(`/api/history/${id}`, {}, config);
    } catch (err) {
      console.error('Error adding to history:', err);
    }
  };

  const handleAddComment = async () => {
    try {
      const token = localStorage.getItem('token');
      const config = {
        headers: {
          'x-auth-token': token,
        },
      };
      const res = await axios.post(
        `/api/movies/${id}/comments`,
        { text: comment, rating: userRating },
        config
      );
      setContent((prev) => ({
        ...prev,
        comments: res.data,
      }));
      setComment('');
      setUserRating(0);
    } catch (err) {
      console.error('Error adding comment:', err);
    }
  };

  if (error) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4 }}>
        <Typography color="error">{error}</Typography>
      </Container>
    );
  }

  if (!content) {
    return (
      <Container maxWidth="lg" sx={{ mt: 4 }}>
        <Typography>Loading...</Typography>
      </Container>
    );
  }

  const youtubeId = content.youtubeTrailer ? content.youtubeTrailer.split('v=')[1] : null;

  return (
    <Container maxWidth="xl">
      {loading ? (
        <Box display="flex" justifyContent="center" alignItems="center" minHeight="80vh">
          <CircularProgress />
        </Box>
      ) : error ? (
        <Alert severity="error" sx={{ mt: 4 }}>{error}</Alert>
      ) : content && (
        <>
          <Grid container spacing={4}>
            <Grid item xs={12} md={4}>
              <img
                src={content.poster}
                alt={content.title}
                style={{ width: '100%', borderRadius: '8px' }}
              />
            </Grid>
            <Grid item xs={12} md={8}>
              <Paper elevation={3} sx={{ p: 3 }}>
                <Typography variant="h4" component="h1" gutterBottom>
                  {content.title}
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <Rating value={content.rating / 2} readOnly precision={0.5} />
                  <Typography variant="body1" sx={{ ml: 1 }}>
                    {content.rating.toFixed(1)}
                  </Typography>
                </Box>
                <Typography variant="body1" paragraph>
                  {content.description}
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  Genre: {content.genres.join(', ')}
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  Release Date: {new Date(content.releaseDate).toLocaleDateString()}
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  Duration: {content.duration}
                </Typography>
                <Box sx={{ mt: 3 }}>
                  {content.bookMyShowLink && (
                    <Button
                      variant="contained"
                      color="primary"
                      href={content.bookMyShowLink}
                      target="_blank"
                      sx={{ mr: 2 }}
                    >
                      Book Tickets
                    </Button>
                  )}
                  {content.wikipediaLink && (
                    <Button
                      variant="outlined"
                      color="primary"
                      href={content.wikipediaLink}
                      target="_blank"
                      sx={{ mr: 2 }}
                    >
                      Learn More
                    </Button>
                  )}
                  <Button
                    variant="outlined"
                    color="secondary"
                    onClick={handleAddToHistory}
                  >
                    Add to History
                  </Button>
                </Box>
              </Paper>
            </Grid>
            <Grid item xs={12}>
              <Paper elevation={3} sx={{ p: 3 }}>
                <Tabs value={activeTab} onChange={(e, newValue) => setActiveTab(newValue)}>
                  <Tab label="Trailer" />
                  <Tab label="Comments" />
                  {content.type === 'series' && <Tab label="Episodes" />}
                </Tabs>
                <Box sx={{ mt: 2 }}>
                  {activeTab === 0 && (
                    <Box>
                      {youtubeId ? (
                        <Box sx={{ position: 'relative', paddingTop: '56.25%' }}>
                          <YouTube
                            videoId={youtubeId}
                            opts={{
                              width: '100%',
                              height: '100%',
                              playerVars: {
                                autoplay: 0,
                              },
                            }}
                            style={{
                              position: 'absolute',
                              top: 0,
                              left: 0,
                              width: '100%',
                              height: '100%',
                            }}
                          />
                        </Box>
                      ) : (
                        <Typography>No trailer available</Typography>
                      )}
                    </Box>
                  )}
                  {activeTab === 1 && (
                    <Box>
                      <Box sx={{ mb: 3 }}>
                        <Typography variant="h6" gutterBottom>
                          Add a Comment
                        </Typography>
                        <TextField
                          fullWidth
                          multiline
                          rows={4}
                          value={comment}
                          onChange={(e) => setComment(e.target.value)}
                          placeholder="Write your comment..."
                          sx={{ mb: 2 }}
                        />
                        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                          <Typography component="legend">Your Rating:</Typography>
                          <Rating
                            value={userRating}
                            onChange={(e, newValue) => setUserRating(newValue)}
                          />
                        </Box>
                        <Button
                          variant="contained"
                          onClick={handleAddComment}
                          disabled={!comment.trim()}
                        >
                          Post Comment
                        </Button>
                      </Box>
                      <Divider sx={{ my: 3 }} />
                      <List>
                        {content.comments.map((comment) => (
                          <React.Fragment key={comment._id}>
                            <ListItem alignItems="flex-start">
                              <ListItemAvatar>
                                <Avatar>{comment.user.username[0]}</Avatar>
                              </ListItemAvatar>
                              <ListItemText
                                primary={
                                  <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                    <Typography component="span" variant="subtitle1">
                                      {comment.user.username}
                                    </Typography>
                                    {comment.rating && (
                                      <Rating
                                        value={comment.rating}
                                        readOnly
                                        size="small"
                                        sx={{ ml: 2 }}
                                      />
                                    )}
                                  </Box>
                                }
                                secondary={
                                  <>
                                    <Typography
                                      component="span"
                                      variant="body2"
                                      color="text.primary"
                                    >
                                      {comment.text}
                                    </Typography>
                                    <Typography variant="caption" display="block">
                                      {new Date(comment.createdAt).toLocaleDateString()}
                                    </Typography>
                                  </>
                                }
                              />
                            </ListItem>
                            <Divider variant="inset" component="li" />
                          </React.Fragment>
                        ))}
                      </List>
                    </Box>
                  )}
                  {activeTab === 2 && content.type === 'series' && (
                    <Box>
                      {content.seasons.map((season) => (
                        <Box key={season.seasonNumber} sx={{ mb: 4 }}>
                          <Typography variant="h6" gutterBottom>
                            Season {season.seasonNumber}
                          </Typography>
                          <Grid container spacing={2}>
                            {season.episodes.map((episode) => (
                              <Grid item xs={12} sm={6} md={4} key={episode.episodeNumber}>
                                <Paper elevation={2} sx={{ p: 2 }}>
                                  <Typography variant="subtitle1">
                                    Episode {episode.episodeNumber}: {episode.title}
                                  </Typography>
                                  <Typography variant="body2" color="text.secondary">
                                    {episode.description}
                                  </Typography>
                                  <Typography variant="caption" display="block">
                                    Duration: {episode.duration}
                                  </Typography>
                                </Paper>
                              </Grid>
                            ))}
                          </Grid>
                        </Box>
                      ))}
                    </Box>
                  )}
                </Box>
              </Paper>
            </Grid>
          </Grid>

          {/* Streaming Providers */}
          {providers && providers.results && providers.results.US && (
            <Box sx={{ mt: 4 }}>
              <Typography variant="h5" gutterBottom>
                Where to Watch
              </Typography>
              <Grid container spacing={2}>
                {providers.results.US.flatrate && (
                  <Grid item xs={12} md={6}>
                    <Paper sx={{ p: 2 }}>
                      <Typography variant="h6" gutterBottom>
                        Streaming Services
                      </Typography>
                      <List>
                        {providers.results.US.flatrate.map((provider) => (
                          <ListItem key={provider.provider_id}>
                            <ListItemIcon>
                              <img
                                src={`https://image.tmdb.org/t/p/original${provider.logo_path}`}
                                alt={provider.provider_name}
                                style={{ width: 50, height: 50, objectFit: 'contain' }}
                              />
                            </ListItemIcon>
                            <ListItemText primary={provider.provider_name} />
                          </ListItem>
                        ))}
                      </List>
                    </Paper>
                  </Grid>
                )}
                {providers.results.US.rent && (
                  <Grid item xs={12} md={6}>
                    <Paper sx={{ p: 2 }}>
                      <Typography variant="h6" gutterBottom>
                        Rent or Buy
                      </Typography>
                      <List>
                        {providers.results.US.rent.map((provider) => (
                          <ListItem key={provider.provider_id}>
                            <ListItemIcon>
                              <img
                                src={`https://image.tmdb.org/t/p/original${provider.logo_path}`}
                                alt={provider.provider_name}
                                style={{ width: 50, height: 50, objectFit: 'contain' }}
                              />
                            </ListItemIcon>
                            <ListItemText primary={provider.provider_name} />
                          </ListItem>
                        ))}
                      </List>
                    </Paper>
                  </Grid>
                )}
              </Grid>
            </Box>
          )}

          {/* Similar Content */}
          {similarContent.length > 0 && (
            <Box sx={{ mt: 4 }}>
              <Typography variant="h5" gutterBottom>
                Similar {type === 'movie' ? 'Movies' : 'TV Shows'}
              </Typography>
              <Grid container spacing={3}>
                {similarContent.slice(0, 4).map((item) => (
                  <Grid item xs={12} sm={6} md={3} key={item.id}>
                    <ContentCard content={item} />
                  </Grid>
                ))}
              </Grid>
            </Box>
          )}
        </>
      )}
    </Container>
  );
};

export default MovieDetails;
